// Generated by scripts/sync-core.mjs from mobile/src/state/cache.ts; edit it there and run npm run sync-core.
// What the app last read of a chain, shared by every screen and kept on the
// device: a screen shows the last values at once, and the node's answers for the
// current block replace them, so screens neither wait nor jump. Each chain has
// its own cache, whichever node it was read from; the app starts with the one
// of the chain it last saw. Nothing here goes into a transaction: what one
// needs, such as a nonce, is read from the node when it is built.
import { useEffect, useMemo, useSyncExternalStore } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { hex, unhex } from '@/core/chain/bytes';

/** The saved cache's format; one saved in another is dropped and read again. */
const FORMAT = 1;
const STORAGE_PREFIX = 'ting-id-cache:';
/** Where the chain the app last saw is noted. */
const LAST_CHAIN = 'ting-id-cache-chain';
/** A change is saved once this long passed without another. */
const SAVE_DELAY_MS = 2_000;
/** Values no screen read for this long are not saved again. */
const KEEP_MS = 30 * 86_400_000;

// ---- Values as text ------------------------------------------------------------

/** JSON that also holds the app's bigints, byte strings and maps. */
export function encodeValue(value: unknown): string {
  return JSON.stringify(value, (_key, v: unknown) => {
    if (typeof v === 'bigint') return { $n: v.toString() };
    if (v instanceof Uint8Array) return { $b: hex(v) };
    if (v instanceof Map) return { $m: [...v.entries()] };
    return v;
  });
}

export function decodeValue(text: string): unknown {
  return JSON.parse(text, (_key, v: unknown) => {
    if (!v || typeof v !== 'object' || Array.isArray(v)) return v;
    const o = v as Record<string, unknown>;
    if (Object.keys(o).length !== 1) return v;
    if (typeof o.$n === 'string') return BigInt(o.$n);
    if (typeof o.$b === 'string') return unhex(o.$b);
    if (Array.isArray(o.$m)) return new Map(o.$m as [unknown, unknown][]);
    return v;
  });
}

// ---- One chain's cache -----------------------------------------------------------

export interface CacheEntry {
  value: unknown;
  /** The chain tip the value was read at; empty when it must be read again. */
  version: string;
  /** The value as text, to tell a new read that changed nothing. */
  text: string;
  /** When a read last gave it, in milliseconds. */
  at: number;
}

/** Where a cache is kept: AsyncStorage in the app, a map in tests. */
export interface CacheStorage {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
}

interface Saved {
  format: number;
  entries: [string, string, number, unknown][];
}

function isSaved(v: unknown): v is Saved {
  const s = v as Saved;
  return !!s && typeof s === 'object' && s.format === FORMAT && Array.isArray(s.entries);
}

export class ChainCache {
  /** Counts changes, for screens to notice them. */
  revision = 0;
  /** Counts the times values were to be read again; hooks then read their stale keys. */
  epoch = 0;
  loaded = false;
  private entries = new Map<string, CacheEntry>();
  /** The version each key is being read at: a read that a newer one overtook is dropped. */
  private wanted = new Map<string, string>();
  private listeners = new Set<() => void>();
  private loading: Promise<void> | null = null;
  private saveTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(
    /** The chain, as hex. */
    readonly chain: string,
    private readonly storage: CacheStorage = AsyncStorage,
  ) {}

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  };

  getRevision = (): number => this.revision;

  get(key: string): CacheEntry | undefined {
    return this.entries.get(key);
  }

  /** Whether `key` wants a read at `version`: not read at it, and no read at it on the way. */
  stale(key: string, version: string): boolean {
    return this.entries.get(key)?.version !== version && this.wanted.get(key) !== version;
  }

  /** Notes that reads of `keys` at `version` started. */
  begin(keys: string[], version: string) {
    for (const key of keys) this.wanted.set(key, version);
  }

  /** The value of `key` read at `version`; one that changed nothing keeps the value screens already have. */
  put(key: string, value: unknown, version: string) {
    const wanted = this.wanted.get(key);
    if (wanted !== undefined && wanted !== version) return;
    this.wanted.delete(key);
    const text = encodeValue(value);
    const old = this.entries.get(key);
    if (old && old.text === text) {
      old.version = version;
      old.at = Date.now();
    } else {
      this.entries.set(key, { value, version, text, at: Date.now() });
      this.changed();
    }
    this.scheduleSave();
  }

  /** A read that failed: the key may be read again at the same version. */
  fail(key: string, version: string) {
    if (this.wanted.get(key) === version) this.wanted.delete(key);
  }

  /** Everything is read again, as the user asked to refresh. */
  invalidate() {
    for (const e of this.entries.values()) e.version = '';
    this.wanted.clear();
    this.retry();
  }

  /** Drops every value, and a save on the way: the saved cache is being deleted. */
  clear() {
    if (this.saveTimer) clearTimeout(this.saveTimer);
    this.saveTimer = null;
    this.entries.clear();
    this.wanted.clear();
    this.retry();
  }

  /** Values that are not up to date are read again, as the node answers again. */
  retry() {
    this.epoch++;
    this.changed();
  }

  /** Reads the saved cache once; values read before it finished stay. */
  load(): Promise<void> {
    this.loading ??= (async () => {
      try {
        const text = await this.storage.getItem(STORAGE_PREFIX + this.chain);
        const saved = text ? decodeValue(text) : null;
        if (isSaved(saved)) {
          for (const [key, version, at, value] of saved.entries) {
            if (!this.entries.has(key)) this.entries.set(key, { value, version, text: encodeValue(value), at });
          }
        }
      } catch {
        // An unreadable cache is read again from the node.
      }
      this.loaded = true;
      this.changed();
    })();
    return this.loading;
  }

  private changed() {
    this.revision++;
    for (const l of this.listeners) l();
  }

  private scheduleSave() {
    if (this.saveTimer) clearTimeout(this.saveTimer);
    this.saveTimer = setTimeout(() => this.save(), SAVE_DELAY_MS);
  }

  /** Writes the cache, from the values' text, leaving out ones long unused. */
  save(): Promise<void> {
    if (this.saveTimer) clearTimeout(this.saveTimer);
    this.saveTimer = null;
    // Not before the saved cache was read: that would overwrite it with less.
    if (!this.loaded) return Promise.resolve();
    const since = Date.now() - KEEP_MS;
    const entries = [...this.entries].filter(([, e]) => e.at >= since).map(([key, e]) => `[${JSON.stringify(key)},${JSON.stringify(e.version)},${e.at},${e.text}]`);
    return this.storage.setItem(STORAGE_PREFIX + this.chain, `{"format":${FORMAT},"entries":[${entries.join(',')}]}`).catch(() => {});
  }
}

// ---- The current chain -------------------------------------------------------------

const caches = new Map<string, ChainCache>();
/** The cache of the chain the node is on, or of the one the app last saw while no node answered yet. */
let current: ChainCache | null = null;
const switchListeners = new Set<() => void>();

function cacheFor(chainHex: string): ChainCache {
  let cache = caches.get(chainHex);
  if (!cache) {
    cache = new ChainCache(chainHex);
    caches.set(chainHex, cache);
    cache.load();
  }
  return cache;
}

/** A node answered from chain `chainHex`: its cache is the one screens use from now. */
export function selectChain(chainHex: string): ChainCache {
  if (current?.chain !== chainHex) {
    current = cacheFor(chainHex);
    AsyncStorage.setItem(LAST_CHAIN, chainHex).catch(() => {});
    for (const l of switchListeners) l();
  }
  return current;
}

/** The chain the app is on (hex), or null before any node answered. */
export function currentChain(): string | null {
  return current?.chain ?? null;
}

/** Everything of the current chain is read again: what came from a node found to give wrong answers. */
export function invalidateCurrent() {
  current?.invalidate();
}

/** Every chain's values are dropped, as all saved data is deleted. */
export function forgetCaches() {
  for (const cache of caches.values()) cache.clear();
}

/** Reads the cache of the chain the app last saw, before the first screen shows, so the app starts with the last values. */
export async function openLastCache(): Promise<void> {
  const chainHex = await AsyncStorage.getItem(LAST_CHAIN).catch(() => null);
  if (!chainHex || current) return;
  current = cacheFor(chainHex);
  await current.load();
}

const subscribeSwitch = (listener: () => void) => {
  switchListeners.add(listener);
  return () => {
    switchListeners.delete(listener);
  };
};
const getCurrent = () => current;
const noSubscription = () => () => {};
const noRevision = () => 0;

/** The current chain's cache, null before any node answered; the screen renders again when it changes. */
export function useChainCache(): ChainCache | null {
  const cache = useSyncExternalStore(subscribeSwitch, getCurrent);
  useSyncExternalStore(cache ? cache.subscribe : noSubscription, cache ? cache.getRevision : noRevision);
  return cache;
}

/**
 * The cached values of `keys`, and one call of `read` for the ones not read at
 * `version` (the chain's tip) yet: `read` gets those keys in order and gives
 * their values in the same order. Without a cache or version (no chain yet)
 * nothing is read. `missing`: some key has no value at all yet.
 */
export function useCached<T>(cache: ChainCache | null, keys: string[], version: string | null, read: (stale: string[]) => Promise<T[]>): { values: Map<string, T>; missing: boolean } {
  const keysKey = keys.join('\n');
  const epoch = cache?.epoch ?? 0;
  useEffect(() => {
    if (!cache || !version) return;
    const stale = keys.filter((k) => cache.stale(k, version));
    if (stale.length === 0) return;
    cache.begin(stale, version);
    // A read finishes into the cache even when the screen changed meanwhile: other screens use it.
    read(stale)
      .then((values) => stale.forEach((k, i) => cache.put(k, values[i], version)))
      .catch(() => stale.forEach((k) => cache.fail(k, version)));
  }, [cache, keysKey, version, epoch]); // eslint-disable-line react-hooks/exhaustive-deps
  const revision = cache?.revision ?? 0;
  return useMemo(() => {
    const values = new Map<string, T>();
    let missing = false;
    for (const k of keys) {
      const e = cache?.get(k);
      if (e) values.set(k, e.value as T);
      else missing = true;
    }
    return { values, missing };
  }, [cache, keysKey, revision]); // eslint-disable-line react-hooks/exhaustive-deps
}
